import React, { useEffect, useState } from "react";
import axios from "axios";
import "./AdminDashboard.css";
import { Link } from "react-router-dom";
import { FaUserPlus, FaUsers, FaTruck, FaUserCircle, FaChevronDown, FaChevronUp } from "react-icons/fa";

function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [newUser, setNewUser] = useState({
    username: "",
    email: "",
    password: "",
    role: "USER",
    enabled: true,
  });
  const [editUser, setEditUser] = useState(null);
  const [message, setMessage] = useState("");
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [activeCard, setActiveCard] = useState("view-users"); // State to manage which card content is visible

  const token = localStorage.getItem("token");
  const userEmail = "admin@example.com"; // Hardcoded for example, you can get this from authentication context
  const userName = "Admin"; // Hardcoded for example

  const fetchUsers = async () => {
    try {
      const response = await axios.get("http://localhost:8080/api/admin/users", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setUsers(response.data);
    } catch (error) {
      console.error("Error fetching users:", error);
      setMessage("❌ Failed to load users.");
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleAddUser = async (e) => {
    e.preventDefault();
    try {
      await axios.post("http://localhost:8080/api/admin/users", newUser, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      setMessage("✅ User added successfully!");
      setNewUser({ username: "", email: "", password: "", role: "USER", enabled: true });
      fetchUsers();
    } catch (error) {
      console.error("Error adding user:", error.response?.data || error);
      setMessage("❌ Failed to add user.");
    }
  };

  const handleDeleteUser = async (id) => {
    if (!window.confirm("Are you sure you want to delete this user?")) return;
    try {
      await axios.delete(`http://localhost:8080/api/admin/users/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setMessage("✅ User deleted successfully!");
      fetchUsers();
    } catch (error) {
      console.error("Error deleting user:", error.response?.data || error);
      setMessage("❌ Failed to delete user.");
    }
  };

  const handleEditUser = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:8080/api/admin/users/${editUser.id}`, editUser, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      setMessage("✅ User updated successfully!");
      setEditUser(null);
      fetchUsers();
    } catch (error) {
      console.error("Error editing user:", error.response?.data || error);
      setMessage("❌ Failed to update user.");
    }
  };

  const filteredUsers = users.filter(
    (u) =>
      u.username?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );
  
  // A simple function for logging out
  const handleLogout = () => {
      localStorage.removeItem("token");
      window.location.href = "/login"; // or use navigate from react-router-dom
  };

  return (
    <div className="admin-dashboard-container">
      {/* New Header with Profile Dropdown */}
      <nav className="header-nav">
        <div className="logo">RouteMax</div>
        <div className="profile-menu">
          <div className="profile-toggle" onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}>
            <FaUserCircle className="profile-icon" />
            <span className="profile-name">Admin</span>
            {isProfileDropdownOpen ? <FaChevronUp /> : <FaChevronDown />}
          </div>
          {isProfileDropdownOpen && (
            <div className="profile-dropdown">
              <div className="dropdown-header">
                <p className="user-name">{userName}</p>
                <p className="user-email">{userEmail}</p>
              </div>
              <div className="dropdown-divider"></div>
              <button className="dropdown-item" onClick={handleLogout}>Logout</button>
            </div>
          )}
        </div>
      </nav>

      {/* Main Content Area */}
      <div className="content-area">
        <div className="welcome-section">
          <h1 className="welcome-title">Welcome, Admin 👋</h1>
          <p className="welcome-subtitle">
            Manage user accounts and parcel information with ease.
          </p>
        </div>

        {/* New Cards Section */}
        <div className="card-container">
          <div className={`card ${activeCard === 'add-user' ? 'active' : ''}`} onClick={() => setActiveCard("add-user")}>
            <h3 className="card-title">
              <FaUserPlus className="card-icon" /> Add User
            </h3>
            <p className="card-text">
              Create a new user account with a specific role (USER or ADMIN).
            </p>
          </div>
          <div className={`card ${activeCard === 'view-users' ? 'active' : ''}`} onClick={() => setActiveCard("view-users")}>
            <h3 className="card-title">
              <FaUsers className="card-icon" /> View Users
            </h3>
            <p className="card-text">
              Search, view, edit, and delete all user accounts.
            </p>
          </div>
          <div className={`card ${activeCard === 'manage-parcels' ? 'active' : ''}`} onClick={() => setActiveCard("manage-parcels")}>
            <h3 className="card-title">
              <FaTruck className="card-icon" /> Manage Parcels
            </h3>
            <p className="card-text">
              Go to the parcels page to track, manage, and update shipments.
            </p>
            <Link to="/parcels" className="card-link">
              Go to Parcels →
            </Link>
          </div>
        </div>

        {/* Conditional Content based on activeCard state */}
        <div className="card-content-area">
          {message && (
            <p className={`message ${message.includes("success") ? "success" : "error"}`}>
              {message}
            </p>
          )}

          {activeCard === "add-user" && (
            <div className="form-section">
              <h2 className="section-title">Add New User</h2>
              <form onSubmit={handleAddUser} className="add-user-form">
                <input
                  type="text"
                  placeholder="Username"
                  value={newUser.username}
                  onChange={(e) => setNewUser({ ...newUser, username: e.target.value })}
                  required
                />
                <input
                  type="email"
                  placeholder="Email"
                  value={newUser.email}
                  onChange={(e) => setNewUser({ ...newUser, email: e.target.value })}
                  required
                />
                <input
                  type="password"
                  placeholder="Password"
                  value={newUser.password}
                  onChange={(e) => setNewUser({ ...newUser, password: e.target.value })}
                  required
                />
                <select
                  value={newUser.role}
                  onChange={(e) => setNewUser({ ...newUser, role: e.target.value })}
                >
                  <option value="USER">USER</option>
                  <option value="ADMIN">ADMIN</option>
                </select>
                <button type="submit">Add User</button>
              </form>
            </div>
          )}

          {activeCard === "view-users" && (
            <div className="table-section">
              <h2 className="section-title">User Management</h2>
              <input
                type="text"
                placeholder="Search by username or email"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="search-input"
              />

              {editUser && (
                <form onSubmit={handleEditUser} className="edit-user-form">
                  <h3>Edit User: {editUser.username}</h3>
                  <input
                    type="text"
                    value={editUser.username}
                    onChange={(e) => setEditUser({ ...editUser, username: e.target.value })}
                    required
                  />
                  <input
                    type="email"
                    value={editUser.email}
                    onChange={(e) => setEditUser({ ...editUser, email: e.target.value })}
                    required
                  />
                  <input
                    type="password"
                    placeholder="(leave blank to keep same)"
                    onChange={(e) => setEditUser({ ...editUser, password: e.target.value })}
                  />
                  <select
                    value={editUser.role}
                    onChange={(e) => setEditUser({ ...editUser, role: e.target.value })}
                  >
                    <option value="USER">USER</option>
                    <option value="ADMIN">ADMIN</option>
                  </select>
                  <button type="submit">Save Changes</button>
                  <button type="button" onClick={() => setEditUser(null)}>
                    Cancel
                  </button>
                </form>
              )}

              <table className="users-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Username</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredUsers.map((u) => (
                    <tr key={u.id}>
                      <td>{u.id}</td>
                      <td>{u.username}</td>
                      <td>{u.email}</td>
                      <td>{u.role}</td>
                      <td>
                        <button onClick={() => setEditUser(u)}>Edit</button>
                        <button onClick={() => handleDeleteUser(u.id)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {activeCard === "manage-parcels" && (
            // This section can be a simple placeholder since you have a dedicated page for it
            <div className="manage-parcels-info">
              <h3>Parcel Management</h3>
              <p>Click the button below to navigate to the parcel management dashboard.</p>
              <Link to="/parcels" className="track-parcel-btn">Go to Parcels</Link>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default AdminDashboard;
